const config = {
  org_id: '9f5a0e68-7f42-4ca6-bf0d-3ed6bb0c6bf1',
  company_id: 1647948,
  yclients_partner_token: '{{$env.YCLIENTS_PARTNER_TOKEN}}',
  yclients_user_token: '{{$env.YCLIENTS_USER_TOKEN}}',
  supabase_url: '{{$env.SUPABASE_URL}}',
  supabase_service_role_key: '{{$env.SUPABASE_SERVICE_ROLE_KEY}}',
  fetch_count: 100,
  lookback_minutes: 180,
  yandex_maps_url: 'https://yandex.ru/maps/org/PLACEHOLDER',
  two_gis_url: 'https://go.2gis.com/PLACEHOLDER',
  whatsapp_send_url: 'https://green-api.example/send-whatsapp',
  max_send_url: 'https://green-api.example/send-max',
  followup_template: '{{name}}, спасибо за визит на {{service}}. Будем благодарны за отзыв: Яндекс Карты {{yandex_maps_url}} 2ГИС {{two_gis_url}}. Если захотите записаться снова, просто ответьте на это сообщение.'
};

if (!config.org_id) throw new Error('org_id is required in Build Follow-up Config');
if (!Number.isFinite(Number(config.company_id)) || Number(config.company_id) <= 0) throw new Error('company_id must be positive');
if (!config.yclients_partner_token || !config.yclients_user_token) throw new Error('YClients tokens are required');
if (!config.supabase_url || !config.supabase_service_role_key) throw new Error('Supabase credentials are required');
if (!String(config.followup_template || '').trim()) throw new Error('followup_template is required');
if (!String(config.yandex_maps_url || '').trim()) throw new Error('yandex_maps_url is required');
if (!String(config.two_gis_url || '').trim()) throw new Error('two_gis_url is required');
if (!String(config.whatsapp_send_url || '').trim()) throw new Error('whatsapp_send_url is required');
if (!String(config.max_send_url || '').trim()) throw new Error('max_send_url is required');

return [{
  json: {
    request_id: `yclients_visit_followup_${Date.now()}`,
    workflow_name: '22_YClients_Attended_Visit_Followup',
    org_id: config.org_id,
    company_id: Number(config.company_id),
    yclients_partner_token: config.yclients_partner_token,
    yclients_user_token: config.yclients_user_token,
    supabase_url: config.supabase_url,
    supabase_service_role_key: config.supabase_service_role_key,
    fetch_count: Number(config.fetch_count) > 0 ? Math.min(Number(config.fetch_count), 200) : 100,
    lookback_minutes: Number(config.lookback_minutes) > 0 ? Number(config.lookback_minutes) : 180,
    yandex_maps_url: String(config.yandex_maps_url).trim(),
    two_gis_url: String(config.two_gis_url).trim(),
    whatsapp_send_url: String(config.whatsapp_send_url).trim(),
    max_send_url: String(config.max_send_url).trim(),
    followup_template: String(config.followup_template).trim()
  }
}];

function parseDate(value) {
  if (!value) return null;
  const date = new Date(String(value));
  return Number.isNaN(date.getTime()) ? null : date;
}

function formatDateTime(value) {
  const date = parseDate(value);
  if (!date) return '';
  return new Intl.DateTimeFormat('ru-RU', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'Asia/Novosibirsk'
  }).format(date);
}

function renderTemplate(template, row) {
  return String(template || '')
    .replace(/{{\s*name\s*}}/gi, row.first_name || row.client_display_name || 'Здравствуйте')
    .replace(/{{\s*service\s*}}/gi, row.service_name || 'услуга')
    .replace(/{{\s*master\s*}}/gi, row.master_name || 'мастер')
    .replace(/{{\s*datetime\s*}}/gi, row.record_datetime_label || '')
    .replace(/{{\s*yandex_maps_url\s*}}/gi, row.yandex_maps_url || '')
    .replace(/{{\s*two_gis_url\s*}}/gi, row.two_gis_url || '');
}

const cfg = $('Build Follow-up Config').first().json || {};
const response = $input.first().json || {};
const rows = Array.isArray(response.data) ? response.data : [];
const cutoff = new Date(Date.now() - Number(cfg.lookback_minutes || 180) * 60 * 1000);
const seen = new Set();
const records = [];

for (const row of rows) {
  const recordId = Number(row?.id || 0);
  const attendance = Number(row?.attendance ?? row?.visit_attendance ?? 0);
  const clientId = Number(row?.client?.id || 0);
  const lastChange = parseDate(row?.last_change_date);
  if (!Number.isFinite(recordId) || recordId <= 0) continue;
  if (seen.has(recordId)) continue;
  if (attendance !== 1) continue;
  if (!Number.isFinite(clientId) || clientId <= 0) continue;
  if (!lastChange || lastChange < cutoff) continue;
  seen.add(recordId);

  const clientDisplayName = String(row?.client?.display_name || row?.client?.name || '').trim();
  const firstName = clientDisplayName.split(/\s+/).filter(Boolean)[0] || 'Здравствуйте';
  const serviceName = Array.isArray(row?.services) && row.services.length > 0 ? String(row.services[0]?.title || '').trim() : '';
  const masterName = String(row?.staff?.name || '').trim();
  const recordDatetime = row?.datetime || row?.date || null;
  const recordDatetimeLabel = formatDateTime(recordDatetime);
  const messageText = renderTemplate(cfg.followup_template, {
    first_name: firstName,
    client_display_name: clientDisplayName,
    service_name: serviceName,
    master_name: masterName,
    record_datetime_label: recordDatetimeLabel,
    yandex_maps_url: cfg.yandex_maps_url,
    two_gis_url: cfg.two_gis_url
  }).trim();
  if (!messageText) continue;

  records.push({
    org_id: cfg.org_id,
    request_id: cfg.request_id,
    yclients_record_id: recordId,
    yclients_client_id: clientId,
    yclients_visit_id: Number(row?.visit_id || 0) || null,
    attendance,
    message_text: messageText,
    service_name: serviceName || null,
    master_name: masterName || null,
    record_date: recordDatetime ? new Date(recordDatetime).toISOString() : null,
    last_change_date: lastChange.toISOString()
  });
}

return [{ json: { ...cfg, records } }];

function getRows(name) {
  try {
    return $(name).all().map((item) => item.json || {});
  } catch (error) {
    return [];
  }
}

function normalizeDigits(value) {
  return String(value || '').replace(/\D+/g, '');
}

function isTelegramAllowed(row) {
  const blocked = String(row?.blocked || '').toLowerCase();
  const allowMarketing = String(row?.allow_marketing || '').toLowerCase();
  const canMessage = String(row?.can_message || '').toLowerCase();
  if (['true', 'yes', '1'].includes(blocked)) return false;
  if (['false', 'no', '0'].includes(allowMarketing)) return false;
  if (['false', 'no', '0'].includes(canMessage)) return false;
  return true;
}

const batch = $('Normalize Attended Records').first().json || {};
const records = Array.isArray(batch.records) ? batch.records : [];
const clients = getRows('Get Clients');
const telegramUsers = getRows('Get Telegram Users');
const whatsappUsers = getRows('Get WhatsApp Users');
const maxUsers = getRows('Get Max Users');

const ycIds = new Set(records.map((row) => String(row.yclients_client_id || '')).filter(Boolean));
const clientsByYcId = new Map();
for (const row of clients) {
  const ycId = String(row.yc_id || '').trim();
  if (!ycId || !ycIds.has(ycId)) continue;
  if (!clientsByYcId.has(ycId)) clientsByYcId.set(ycId, row);
}

const tgByClient = new Map();
for (const row of telegramUsers) {
  if (!row.client_id || !row.user_id) continue;
  if (!isTelegramAllowed(row)) continue;
  if (!tgByClient.has(row.client_id)) tgByClient.set(row.client_id, String(row.user_id));
}

const waByClient = new Map();
for (const row of whatsappUsers) {
  if (!row.client_id || !row.user_id) continue;
  if (row.blocked === true) continue;
  if (row.allow_marketing === false) continue;
  if (row.can_message === false) continue;
  if (!waByClient.has(row.client_id)) waByClient.set(row.client_id, String(row.user_id));
}

const maxByClient = new Map();
for (const row of maxUsers) {
  const clientId = row.client_id;
  const userId = row.user_id || row.channel_user_id;
  if (!clientId || !userId) continue;
  const blocked = String(row.blocked || '').toLowerCase();
  const allowMarketing = String(row.allow_marketing || '').toLowerCase();
  const canMessage = String(row.can_message || '').toLowerCase();
  if (['true', 'yes', '1'].includes(blocked)) continue;
  if (['false', 'no', '0'].includes(allowMarketing)) continue;
  if (['false', 'no', '0'].includes(canMessage)) continue;
  if (!maxByClient.has(clientId)) maxByClient.set(clientId, String(userId));
}

const messages = [];
let missingClientCount = 0;
let missingMessengerCount = 0;
let duplicateCount = 0;

for (const row of records) {
  const client = clientsByYcId.get(String(row.yclients_client_id));
  if (!client) {
    missingClientCount += 1;
    continue;
  }

  const lastRecordId = String(client.last_yclients_followup_record_id || '').trim();
  const currentRecordId = String(row.yclients_record_id || '').trim();
  if (lastRecordId && currentRecordId && lastRecordId === currentRecordId) {
    duplicateCount += 1;
    continue;
  }

  let selectedChannel = null;
  let selectedTarget = null;

  const clientTelegramId = String(client.telegram_user_id || '').trim();
  if (clientTelegramId) {
    selectedChannel = 'telegram';
    selectedTarget = clientTelegramId;
  } else if (tgByClient.has(client.id)) {
    selectedChannel = 'telegram';
    selectedTarget = tgByClient.get(client.id);
  } else if (waByClient.has(client.id)) {
    selectedChannel = 'whatsapp';
    const raw = String(waByClient.get(client.id));
    selectedTarget = raw.includes('@') ? raw : `${normalizeDigits(raw)}@c.us`;
  } else if (maxByClient.has(client.id)) {
    selectedChannel = 'max';
    selectedTarget = maxByClient.get(client.id);
  }

  if (!selectedChannel || !selectedTarget) {
    missingMessengerCount += 1;
    continue;
  }

  messages.push({
    org_id: row.org_id,
    client_id: client.id,
    client_fullname: client.fullname || null,
    selected_channel: selectedChannel,
    selected_target: selectedTarget,
    yclients_record_id: row.yclients_record_id,
    yclients_visit_id: row.yclients_visit_id,
    yclients_client_id: row.yclients_client_id,
    message_text: row.message_text,
    whatsapp_send_url: batch.whatsapp_send_url,
    max_send_url: batch.max_send_url,
    supabase_url: batch.supabase_url,
    supabase_service_role_key: batch.supabase_service_role_key
  });
}

return [{
  json: {
    request_id: batch.request_id,
    org_id: batch.org_id,
    source_records_count: records.length,
    missing_client_count: missingClientCount,
    missing_messenger_count: missingMessengerCount,
    duplicate_count: duplicateCount,
    messages_count: messages.length,
    messages
  }
}];

const source = $('Explode Messages').item.json || {};
const claimRows = $input.all().map((item) => item.json || {}).filter(Boolean);
if (claimRows.length === 0) return [];
return [{ json: { ...source, claim_row: claimRows[0] } }];

const count = $input.all().length;
const batch = $('Assemble Messages Batch').first().json || {};
return [{ json: { ok: true, status: 'completed', request_id: batch.request_id, org_id: batch.org_id, source_records_count: batch.source_records_count || 0, missing_client_count: batch.missing_client_count || 0, missing_messenger_count: batch.missing_messenger_count || 0, duplicate_count: batch.duplicate_count || 0, sent_count: count, errors: [] } }];
